import React from 'react';
import './App.css';

function App() {
  return (
    <div className="app">
      <h1>Workie</h1>
      <p>Login to your account</p>
      <form className="login-form" onSubmit={(e) => e.preventDefault()}>
        <input 
          type="email" 
          placeholder="Email address" 
          required
        />
        <input 
          type="password" 
          placeholder="Password" 
          required
        />
        <button type="submit">Login</button>
      </form>
    </div>
  );
}

export default App;
